mapper.select:
SELECT h.hospital_id, h.record_id, h.pet_id, h.client_id, h.doctor_id, h.room_no, h.in_time, h.out_time, h.daily_fee, h.bed_fee, h.nursing_fee, h.infusion_fee, h.deposit, h.days, h.status, h.note, h.create_time, p.pet_name, c.client_name, d.doctor_name, r.diagnosis FROM hospital_record h LEFT JOIN pet p ON h.pet_id = p.pet_id LEFT JOIN client c ON h.client_id = c.client_id LEFT JOIN doctor d ON h.doctor_id = d.doctor_id LEFT JOIN medical_record r ON h.record_id = r.record_id WHERE h.is_del = 0
AND h.status = #{status}
ORDER BY h.status ASC, h.in_time DESC
